const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Punjab and Haryana regions (approximate boundaries)
  const punjab = ee.Geometry.Polygon([
    [[73.5, 29.5], [76.8, 29.5], [76.8, 32.5], [73.5, 32.5], [73.5, 29.5]]
  ]);

  const haryana = ee.Geometry.Polygon([
    [[74.5, 27.5], [77.5, 27.5], [77.5, 30.8], [74.5, 30.8], [74.5, 27.5]]
  ]);

  const region = punjab.union(haryana);

  // Define time periods
  const start2022 = '2022-11-01';
  const end2022 = '2022-11-30';
  const start2024 = '2024-11-01';
  const end2024 = '2024-11-30';

  // Load VIIRS active fire data
  const viirs2022 = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
    .filterDate(start2022, end2022)
    .filterBounds(region);

  const viirs2024 = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
    .filterDate(start2024, end2024)
    .filterBounds(region);

  // Check collection sizes
  const size2022 = viirs2022.size().getInfo();
  const size2024 = viirs2024.size().getInfo();

  console.log(`Nov 2022 Images: ${size2022}`);
  console.log(`Nov 2024 Images: ${size2024}`);

  if (size2022 === 0 || size2024 === 0) {
    console.log('Missing data for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Count fires by summing the fire mask band
  const fires2022 = viirs2022.select('FireMask').mosaic();
  const fires2024 = viirs2024.select('FireMask').mosaic();

  const count2022Result = fires2022.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const count2024Result = fires2024.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const fireCount2022 = count2022Result.get('FireMask').getInfo();
  const fireCount2024 = count2024Result.get('FireMask').getInfo();

  console.log(`Fire pixels Nov 2022: ${fireCount2022}`);
  console.log(`Fire pixels Nov 2024: ${fireCount2024}`);

  // Validation
  if (fireCount2022 === null || fireCount2024 === null || 
      isNaN(fireCount2022) || isNaN(fireCount2024)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare fire counts
  if (fireCount2024 < fireCount2022) {
    console.log('2024 fires < 2022 fires: LOWER');
    console.log('<answer>A</answer>');
  } else {
    console.log('2024 fires >= 2022 fires: NOT LOWER');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
